CREATE TABLE IF NOT EXISTS administrators (username VARCHAR(80) PRIMARY KEY, password_hash VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS devices (id VARCHAR(80) PRIMARY KEY, token_hash VARCHAR(255) NOT NULL, revision BIGINT NOT NULL DEFAULT -1, snapshot CLOB, last_seen BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS commands (id VARCHAR(80) PRIMARY KEY, device_id VARCHAR(80) NOT NULL, base_revision BIGINT NOT NULL, snapshot CLOB NOT NULL, status VARCHAR(20) NOT NULL, message VARCHAR(500) NOT NULL, created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, FOREIGN KEY(device_id) REFERENCES devices(id));
CREATE INDEX IF NOT EXISTS idx_commands_device ON commands(device_id,status);
CREATE TABLE IF NOT EXISTS templates (id VARCHAR(80) PRIMARY KEY, name VARCHAR(80) NOT NULL, states CLOB NOT NULL);
CREATE TABLE IF NOT EXISTS settings (name VARCHAR(80) PRIMARY KEY, setting_value VARCHAR(255) NOT NULL);
